class Mover{
  r;
  location;
  velocity;
  acceleration;
  size;
  mass;
  G;

  constructor(r_, x, y, size_, mass_){
    mass = mass_;
    location = new PVector (x,y);
    velocity = new PVector (0,0);
    acceleration = new PVector (0,0);
    size = size_;
    G=0.1;
    r = r_;
  }

  function update(){
    location.add(velocity);
    velocity.add(acceleration);
    acceleration.mult(0);
  }

  function display(){

    fill(245);
    pushMatrix();
    translate(location.x, location.y);
    r+=0.5;
    rotate(radians(r));
    stroke(245);

    line(0,0,10,10);
    noStroke();
    rect(0, 0, size, size);
    popMatrix();
  }


    attract(m){
    var force = PVector.sub(m.location, location);
    let distance = force.mag();
       //constrain distance
     distance = constrain(distance, 10.0, 30.0);
    force.normalize();
    let strength = (G * mass * m.mass) / (distance * distance);
    force.mult(strength);
    return force;
    }


  function applyForce(force){
    //f = ma
    force.div(mass);
    acceleration.add(force); 
  }
  function checkEdge(){
    if (location.x<0){
      location.x = 0;
      velocity.x = -velocity.x;
    }else if (location.x>width){
      location.x = width;
      velocity.x = -velocity.x;
    }
    if (location.y>height){
      location.y = height;
      velocity.y = -velocity.y;
    }else if (location.y < 0){
      location.y =0;
      velocity.y = -velocity.y;
    }

  }


}

